command:
$ErrorActionPreference='Stop'
Set-Location -LiteralPath 'C:\Users\ikuto\projects\conway-99-graph'
$taskPlanPath='acceleration/results/20261003_independent_review/wave41_transition_calibration_launch01/plan.json'
if((Get-FileHash -Algorithm SHA256 -LiteralPath $taskPlanPath).Hash.ToLower() -ne '5ec11a4efc79046dc95bb8cc7e9d98b661c5b9c2b931b9c60ea0f0224f53e682'){throw 'PLAN_HASH'}
$p=Get-Content -Raw -LiteralPath $taskPlanPath|ConvertFrom-Json
$pins=[ordered]@{}
foreach($row in $p.immutable_inputs_sha256.PSObject.Properties){$h=(Get-FileHash -Algorithm SHA256 -LiteralPath $row.Name).Hash.ToLower();if($h -ne $row.Value){throw ('INPUT_HASH '+$row.Name)};$pins[$row.Name]=$h}
$protected=[ordered]@{'CLAIMS.yaml'=(Get-FileHash -Algorithm SHA256 -LiteralPath CLAIMS.yaml).Hash.ToLower();'.git/index'=(Get-FileHash -Algorithm SHA256 -LiteralPath .git/index).Hash.ToLower()}
if($protected['CLAIMS.yaml'] -ne '10b7636dafced40101ccf257d5f80468914f53aa2ee2d3c89db43be268bdcc09' -or $protected['.git/index'] -ne '8bcd46056145e09d225a01e553151abd1958364077a85b5c6d1bc33fe4f4cacd'){throw 'PROTECTED_HASH'}
$ob=Get-Content -Raw -LiteralPath acceleration/results/20261003_independent_review/wave41_transition_windows_observation01.json|ConvertFrom-Json
if(-not $ob.launch_admissible -or @($ob.unknown_recognized_workers).Count -ne 0){throw 'WORKER_OBSERVATION'}
foreach($name in @('acceleration/results/20261003_independent_review/wave41_transition_calibration01','acceleration/results/20261003_independent_review/wave41_transition_calibration_supervision01')){if(Test-Path -LiteralPath $name){throw 'OUTPUT_EXISTS'}}
$head=(& 'C:\Program Files\Git\cmd\git.exe' rev-parse HEAD).Trim();if($LASTEXITCODE -ne 0 -or $head -ne '00ffb6fdd7d91bd38269e1cc5e6b214ebf7591c8'){throw 'HEAD_HASH'}
$out='acceleration/results/20261003_independent_review/wave41_transition_calibration_admission01.json';if(Test-Path -LiteralPath $out){throw 'ADMISSION_EXISTS'}
$r=[ordered]@{schema='WAVE41_METADATA_CALIBRATION_ADMISSION_V1';timestamp=[DateTimeOffset]::UtcNow.ToString('o');status='EXACT_CALIBRATION_ADMISSION_PASS';plan=$taskPlanPath;plan_sha256='5ec11a4efc79046dc95bb8cc7e9d98b661c5b9c2b931b9c60ea0f0224f53e682';inputs_sha256=$pins;immutable_members=$pins.Count;historical_protected_execution_state=$protected;protected_observation_note='ROOT expressly authorized unchanged5ec11 after registration terminal; old plan a4 is historical observation only. Actual new10b ledger is observed/protected separately, outside immutable input pins.';HEAD=$head;windows_observation=$ob.timestamp;unknown_recognized_workers=0;mathematical_replays=0;ledger_mutations=0;index_mutations=0}
[IO.File]::WriteAllText((Join-Path (Get-Location) $out),(($r|ConvertTo-Json -Depth 10)+"`n"),[Text.UTF8Encoding]::new($false))
[pscustomobject]@{status=$r.status;immutable_members=$pins.Count;sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $out).Hash.ToLower()}|ConvertTo-Json -Compress
